"use client"

/** @responsibility Renders a flow (Sankey) diagram — node bars, proportional ribbons, and labels — that fills its host's box, with hover emphasis and controllable link selection. Geometry comes from flow-chart-layout. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  computeFlowChartLayout,
  flowChartCenterlinePath,
  flowChartRibbonPath,
  type FlowChartAlign,
  type FlowChartLayout,
  type FlowChartLayoutIssue,
  type FlowChartLayoutNode,
} from "./flow-chart-layout"

/** A flow endpoint. */
export interface FlowChartNode {
  /** Unique id links refer to. */
  id: string
  /** Text shown beside the node bar. Defaults to the id. */
  label?: string
  /**
   * Optional CSS color for the bar and the ribbons leaving it. Omitted,
   * nodes cycle through the chart's `palette`.
   */
  color?: string
}

/**
 * Pastel tints node bars cycle through by default — dilute enough that
 * overlapping ribbons stay readable, distinct enough that each origin's
 * flows read as one family: peach, aqua, lilac, butter, rose, sky, sage.
 */
export const flowChartPalette: readonly string[] = Object.freeze([
  "oklch(0.87 0.07 45)",
  "oklch(0.86 0.07 185)",
  "oklch(0.84 0.08 310)",
  "oklch(0.89 0.08 100)",
  "oklch(0.85 0.07 5)",
  "oklch(0.85 0.06 235)",
  "oklch(0.87 0.07 150)",
])

/** A weighted flow between two nodes. */
export interface FlowChartLink {
  /**
   * Stable id for selection. Defaults to `${source}→${target}`, so parallel
   * links between the same pair need explicit ids.
   */
  id?: string
  source: string
  target: string
  value: number
}

/** Everything known about a node when a label or detail is rendered. */
export interface FlowChartNodeContext {
  node: FlowChartNode
  /** Flow through the node: max of incoming and outgoing sums. */
  value: number
  inValue: number
  outValue: number
  /** Zero-based column the node landed in. */
  column: number
  columnCount: number
  /** Sum of node values in this node's column. */
  columnTotal: number
}

/** Properties accepted by the FlowChart. */
export interface FlowChartProps
  extends Omit<React.ComponentProps<"div">, "onSelect"> {
  nodes: readonly FlowChartNode[]
  links: readonly FlowChartLink[]
  /** Pixel width of each node bar. */
  nodeWidth?: number
  /** Minimum vertical gap between bars in a column. */
  nodeGap?: number
  /** Ribbon bend, 0 (straight taper) to 1 (full S curve). */
  curvature?: number
  /** Column placement: "justify" (default), "left", "right", or "center". */
  align?: FlowChartAlign
  /**
   * Crossing-minimization passes over each column's node order (d3-style
   * barycenter relaxation). 0 (default) keeps the input order.
   */
  iterations?: number
  /** Flow direction: columns left-to-right (default) or top-to-bottom. */
  orientation?: "horizontal" | "vertical"
  /**
   * How ribbons take color: "source" (default) inherits the source node's
   * tint, "target" the target's, and "gradient" blends source into target
   * along the ribbon.
   */
  linkColor?: "source" | "target" | "gradient"
  /**
   * Width of the label gutters reserved left and right of the diagram.
   * Zero hides the labels entirely.
   */
  labelWidth?: number
  /** Formats a flow value wherever one is shown. */
  formatValue?: (value: number) => string
  /**
   * Second label line under a node's name — defaults to the formatted node
   * value. Return null to drop the line for that node.
   */
  renderNodeDetail?: (context: FlowChartNodeContext) => React.ReactNode
  /** Accessible name for a link. Defaults to "source to target, value". */
  linkLabel?: (link: FlowChartLink) => string
  /**
   * Tints nodes cycle through in input order; a node's own `color` wins.
   * Pass null for the all-neutral wash.
   */
  palette?: readonly string[] | null
  /** Called as the pointer enters or leaves a ribbon. */
  onHoveredLinkChange?: (
    linkId: string | null,
    link: FlowChartLink | null,
  ) => void
  /**
   * Arbitrary content floated beside the pointer while a ribbon or bar is
   * hovered — a stat line, a Card, anything. Return null to skip a
   * particular hover.
   */
  renderHoverDetail?: (hover: FlowChartHoverContext) => React.ReactNode
  /**
   * Called whenever the set of tolerated data problems changes — dropped
   * links waiting on absent nodes, duplicate nodes, cycle repairs — and
   * once after the first layout to establish the initial state. While
   * data streams in, transient issues come and go; once the stream
   * settles, an empty array is the definitive "everything rendered"
   * signal and anything else is a data error worth surfacing.
   */
  onLayoutIssues?: (issues: FlowChartLayoutIssue[]) => void
  /** Controlled selected link ids; empty for no selection. */
  selectedLinkIds?: readonly string[]
  /** Initial selection when uncontrolled. */
  defaultSelectedLinkIds?: readonly string[]
  /**
   * Called when the selection changes. A plain click (or Enter or Space)
   * selects just that link; with Command or Ctrl held it toggles the link
   * into the existing selection instead.
   */
  onSelectedLinksChange?: (
    linkIds: string[],
    links: FlowChartLink[],
  ) => void
}

/** What the pointer is over when hover detail is rendered. */
export type FlowChartHoverContext =
  | {
      kind: "link"
      linkId: string
      link: FlowChartLink
      source: FlowChartNode
      target: FlowChartNode
    }
  | { kind: "node"; node: FlowChartNode; context: FlowChartNodeContext }

/** Emphasis a bar, ribbon, or label is drawn with. */
type FlowChartEmphasis = "rest" | "active" | "dim"

function linkIdOf(link: FlowChartLink): string {
  return link.id ?? `${link.source}→${link.target}`
}

function useMeasuredBox(ref: React.RefObject<HTMLElement | null>) {
  const [box, setBox] = React.useState<{ width: number; height: number } | null>(
    null,
  )
  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver((entries) => {
      const rect = entries[entries.length - 1].contentRect
      const width = Math.round(rect.width)
      const height = Math.round(rect.height)
      setBox((previous) =>
        previous && previous.width === width && previous.height === height
          ? previous
          : { width, height },
      )
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])
  return box
}

const RIBBON_CLASSES = cn(
  "cursor-pointer fill-[var(--nessa-flow-chart-color,var(--muted-foreground))] opacity-15 outline-none",
  // `d` is a transitionable presentation attribute, so streamed data
  // updates morph ribbons instead of snapping them.
  "transition-[opacity,d] [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "hover:opacity-35",
  "data-[emphasis=active]:opacity-55 data-[emphasis=dim]:opacity-[0.06] data-[emphasis=dim]:hover:opacity-25",
  // Tinted ribbons run a stronger ramp: the dilute pigments read paler
  // than the gray wash at equal opacity.
  "data-[tinted=true]:opacity-50 data-[tinted=true]:hover:opacity-75",
  "data-[tinted=true]:data-[emphasis=active]:opacity-90 data-[tinted=true]:data-[emphasis=dim]:opacity-15 data-[tinted=true]:data-[emphasis=dim]:hover:opacity-40",
  "focus-visible:stroke-ring focus-visible:stroke-2",
)

const BAR_CLASSES = cn(
  "fill-[var(--nessa-flow-chart-color,var(--muted-foreground))] opacity-45",
  "transition-[opacity,x,y,width,height] [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "data-[emphasis=active]:fill-[var(--nessa-flow-chart-color,var(--foreground))] data-[emphasis=active]:opacity-100 data-[emphasis=dim]:opacity-30",
  "data-[tinted=true]:opacity-95 data-[tinted=true]:data-[emphasis=active]:opacity-100 data-[tinted=true]:data-[emphasis=dim]:opacity-40",
)

const LABEL_CLASSES = cn(
  "pointer-events-none absolute flex -translate-y-1/2 flex-col justify-center",
  "nessa-text-3 leading-tight text-muted-foreground",
  "transition-[color,top,left] [transition-duration:var(--nessa-motion-duration-fast)] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
  "data-[emphasis=active]:font-medium data-[emphasis=active]:text-foreground",
)

/**
 * A flow diagram: node bars in columns joined by ribbons whose thickness is
 * proportional to the flow they carry. The chart fills the box the host
 * gives it on both axes. Ribbons are keyboard-focusable buttons; hovering a
 * ribbon or bar isolates the connected flow, and clicking (or Enter or
 * Space) selects a link so the isolation sticks — with Command or Ctrl
 * held, further links toggle into the selection. Selection is
 * host-controllable through `selectedLinkIds`; Escape or a background
 * click clears it. Node bars take soft tints from the palette and every
 * ribbon inherits its source's tint.
 */
function FlowChart({
  nodes,
  links,
  nodeWidth = 12,
  nodeGap = 20,
  curvature = 0.7,
  align = "justify",
  iterations = 0,
  orientation = "horizontal",
  linkColor = "source",
  labelWidth = 132,
  formatValue = (value) => String(value),
  renderNodeDetail,
  linkLabel,
  palette = flowChartPalette,
  onHoveredLinkChange,
  renderHoverDetail,
  onLayoutIssues,
  selectedLinkIds,
  defaultSelectedLinkIds,
  onSelectedLinksChange,
  className,
  ...props
}: FlowChartProps) {
  const plotRef = React.useRef<HTMLDivElement>(null)
  const box = useMeasuredBox(plotRef)

  const [hovered, setHovered] = React.useState<
    { kind: "link"; id: string } | { kind: "node"; id: string } | null
  >(null)
  // Keyboard focus isolates a flow exactly like hover, so Tabbing through
  // the ribbons reads the same as sweeping them with the pointer.
  const [focusedLinkId, setFocusedLinkId] = React.useState<string | null>(null)
  const highlighted =
    hovered ??
    (focusedLinkId !== null
      ? ({ kind: "link", id: focusedLinkId } as const)
      : null)
  const [uncontrolledSelection, setUncontrolledSelection] = React.useState<
    readonly string[]
  >(defaultSelectedLinkIds ?? [])
  const selection = selectedLinkIds ?? uncontrolledSelection
  const selectionSet = React.useMemo(() => new Set(selection), [selection])

  // Duplicate ids keep their FIRST occurrence, matching the layout's own
  // dedupe — labels, tints, and hover detail must describe the node the
  // geometry was computed from.
  const uniqueNodes = React.useMemo(() => {
    const seen = new Set<string>()
    const result: FlowChartNode[] = []
    for (const node of nodes) {
      if (seen.has(node.id)) continue
      seen.add(node.id)
      result.push(node)
    }
    return result
  }, [nodes])
  const nodeById = React.useMemo(
    () => new Map(uniqueNodes.map((node) => [node.id, node])),
    [uniqueNodes],
  )
  const linkIds = React.useMemo(() => links.map(linkIdOf), [links])
  const linkById = React.useMemo(() => {
    const map = new Map<string, FlowChartLink>()
    links.forEach((link, index) => {
      if (!map.has(linkIds[index])) map.set(linkIds[index], link)
    })
    return map
  }, [links, linkIds])

  const vertical = orientation === "vertical"
  const gradientId = React.useId().replace(/:/g, "")
  // Layout runs in flow space: `width` is the flow axis, `height` the
  // cross axis. Vertical charts swap the box into that space and swap
  // back at render time.
  const layout: FlowChartLayout | null = React.useMemo(() => {
    if (!box || box.width <= 0 || box.height <= 0) return null
    return computeFlowChartLayout({
      nodes,
      links,
      width: vertical ? box.height : box.width,
      height: vertical ? box.width : box.height,
      nodeWidth,
      nodeGap,
      align,
      iterations,
    })
  }, [box, nodes, links, nodeWidth, nodeGap, align, iterations, vertical])

  // Report tolerated data problems whenever their set changes — including
  // the change back to none, which is the "stream rendered cleanly" signal.
  const onLayoutIssuesRef = React.useRef(onLayoutIssues)
  onLayoutIssuesRef.current = onLayoutIssues
  const issuesKey = layout
    ? layout.issues
        .map(
          (issue) =>
            `${issue.kind}@${issue.linkIndex ?? ""}@${issue.nodeId ?? ""}:${issue.message}`,
        )
        .join("\n")
    : null
  React.useEffect(() => {
    if (issuesKey === null || !layout) return
    onLayoutIssuesRef.current?.(layout.issues)
    // The layout object changes identity every resize; only a changed
    // issue set should re-notify.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [issuesKey])

  // Nodes cycle through the palette in input order; a node's own color
  // always wins.
  const colorOf = React.useMemo(() => {
    const colors = new Map<string, string>()
    let slot = 0
    for (const node of uniqueNodes) {
      if (node.color) {
        colors.set(node.id, node.color)
      } else if (palette && palette.length > 0) {
        colors.set(node.id, palette[slot % palette.length])
        slot += 1
      }
    }
    return colors
  }, [uniqueNodes, palette])

  const applySelection = (next: string[]) => {
    if (selectedLinkIds === undefined) setUncontrolledSelection(next)
    const chosen = new Set(next)
    onSelectedLinksChange?.(
      next,
      links.filter((link) => chosen.has(linkIdOf(link))),
    )
  }

  /**
   * A plain activation selects just this link (or clears a lone
   * selection of it); an additive one — Command or Ctrl held — toggles
   * the link within the existing selection.
   */
  const activateLink = (link: FlowChartLink, additive: boolean) => {
    const id = linkIdOf(link)
    if (additive) {
      applySelection(
        selectionSet.has(id)
          ? selection.filter((candidate) => candidate !== id)
          : [...selection, id],
      )
      return
    }
    applySelection(
      selection.length === 1 && selection[0] === id ? [] : [id],
    )
  }

  // One pass over the links derives every element's emphasis: links carry
  // their own state, and a node is active exactly when an active link
  // touches it (or it is highlighted itself).
  const { linkEmphasisByIndex, nodeEmphasisById } = React.useMemo(() => {
    const linkMap = new Map<number, FlowChartEmphasis>()
    const nodeMap = new Map<string, FlowChartEmphasis>()
    if (!layout) return { linkEmphasisByIndex: linkMap, nodeEmphasisById: nodeMap }
    const engaged = highlighted !== null || selection.length > 0
    const activeNodes = new Set<string>()
    for (const link of layout.links) {
      const id = linkIds[link.index]
      let emphasis: FlowChartEmphasis
      if (selectionSet.has(id)) emphasis = "active"
      else if (highlighted?.kind === "link") {
        emphasis = highlighted.id === id ? "active" : "dim"
      } else if (highlighted?.kind === "node") {
        emphasis =
          link.source === highlighted.id || link.target === highlighted.id
            ? "active"
            : "dim"
      } else {
        emphasis = selection.length > 0 ? "dim" : "rest"
      }
      linkMap.set(link.index, emphasis)
      if (emphasis === "active") {
        activeNodes.add(link.source)
        activeNodes.add(link.target)
      }
    }
    for (const node of layout.nodes) {
      nodeMap.set(
        node.id,
        !engaged
          ? "rest"
          : (highlighted?.kind === "node" && highlighted.id === node.id) ||
              activeNodes.has(node.id)
            ? "active"
            : "dim",
      )
    }
    return { linkEmphasisByIndex: linkMap, nodeEmphasisById: nodeMap }
  }, [layout, linkIds, selectionSet, selection.length, highlighted])

  const defaultLinkLabel = (link: FlowChartLink) => {
    const sourceLabel = nodeById.get(link.source)?.label ?? link.source
    const targetLabel = nodeById.get(link.target)?.label ?? link.target
    return `${sourceLabel} to ${targetLabel}, ${formatValue(link.value)}`
  }

  const nodeContext = (node: FlowChartLayoutNode): FlowChartNodeContext => ({
    node: nodeById.get(node.id)!,
    value: node.value,
    inValue: node.inValue,
    outValue: node.outValue,
    column: node.column,
    columnCount: layout!.columnCount,
    columnTotal: layout!.columnTotals[node.column],
  })

  // Geometry-derived strings are stable between interaction renders.
  const ribbonPaths = React.useMemo(
    () =>
      layout
        ? layout.links.map((link) =>
            flowChartRibbonPath(link, curvature, vertical),
          )
        : [],
    [layout, curvature, vertical],
  )

  // The hover-detail card follows the pointer imperatively: routing raw
  // pointer coordinates through React state would re-render every ribbon
  // per mousemove just to move a floating card.
  const hoverDetailRef = React.useRef<HTMLDivElement>(null)
  const lastPointerRef = React.useRef<{ x: number; y: number } | null>(null)
  const positionHoverDetail = React.useCallback(() => {
    const element = hoverDetailRef.current
    const point = lastPointerRef.current
    if (!element || !point || !box) return
    // Flip away from the pointer near the plot's far edges so the card
    // stays inside the chart.
    const flipX = point.x > box.width / 2
    const flipY = point.y > box.height / 2
    element.style.left = `${point.x + (flipX ? -12 : 12)}px`
    element.style.top = `${point.y + (flipY ? -12 : 12)}px`
    element.style.transform = `translate(${flipX ? "-100%" : "0"}, ${flipY ? "-100%" : "0"})`
  }, [box])

  const gradientDefs = React.useMemo(() => {
    if (!layout || linkColor !== "gradient") return null
    return (
      <defs>
        {layout.links.map((layoutLink) => {
          const sourceTint = colorOf.get(layoutLink.source)
          const targetTint = colorOf.get(layoutLink.target)
          return (
            <linearGradient
              key={layoutLink.index}
              id={`${gradientId}-${layoutLink.index}`}
              gradientUnits="userSpaceOnUse"
              x1={vertical ? 0 : layoutLink.sourceX}
              y1={vertical ? layoutLink.sourceX : 0}
              x2={vertical ? 0 : layoutLink.targetX}
              y2={vertical ? layoutLink.targetX : 0}
            >
              <stop
                offset="0"
                stopColor={sourceTint}
                className={
                  sourceTint ? undefined : "[stop-color:var(--muted-foreground)]"
                }
              />
              <stop
                offset="1"
                stopColor={targetTint}
                className={
                  targetTint ? undefined : "[stop-color:var(--muted-foreground)]"
                }
              />
            </linearGradient>
          )
        })}
      </defs>
    )
  }, [layout, linkColor, colorOf, vertical, gradientId])

  const hoverDetail =
    renderHoverDetail && hovered && layout
      ? (() => {
          if (hovered.kind === "link") {
            const link = linkById.get(hovered.id)
            if (!link) return null
            return renderHoverDetail({
              kind: "link",
              linkId: hovered.id,
              link,
              source: nodeById.get(link.source)!,
              target: nodeById.get(link.target)!,
            })
          }
          const layoutNode = layout.nodes.find(
            (candidate) => candidate.id === hovered.id,
          )
          if (!layoutNode) return null
          return renderHoverDetail({
            kind: "node",
            node: nodeById.get(hovered.id)!,
            context: nodeContext(layoutNode),
          })
        })()
      : null

  return (
    <div
      data-slot="flow-chart"
      className={cn(
        "relative flex h-full min-h-0 w-full min-w-0 font-sans text-foreground",
        className,
      )}
      onKeyDown={(event) => {
        if (event.key === "Escape" && selection.length > 0) {
          event.stopPropagation()
          applySelection([])
        }
      }}
      {...props}
    >
      <div
        ref={plotRef}
        className={cn(
          "relative min-h-0 min-w-0 flex-1",
          vertical
            ? "my-(--nessa-flow-chart-label-width)"
            : "mx-(--nessa-flow-chart-label-width)",
        )}
        style={
          {
            "--nessa-flow-chart-label-width": `${labelWidth > 0 ? labelWidth : 0}px`,
          } as React.CSSProperties
        }
      >
        {layout ? (
          <svg
            className="absolute inset-0 size-full overflow-visible"
            width={box!.width}
            height={box!.height}
            onPointerDown={(event) => {
              // A press on empty background clears the selection.
              if (
                event.target === event.currentTarget &&
                selection.length > 0
              ) {
                applySelection([])
              }
            }}
            onPointerMove={
              renderHoverDetail
                ? (event) => {
                    const rect = event.currentTarget.getBoundingClientRect()
                    lastPointerRef.current = {
                      x: event.clientX - rect.left,
                      y: event.clientY - rect.top,
                    }
                    positionHoverDetail()
                  }
                : undefined
            }
          >
            {gradientDefs}
            {layout.links.map((layoutLink, renderIndex) => {
              const link = links[layoutLink.index]
              const id = linkIds[layoutLink.index]
              // The ribbon's paint: its anchor node's tint, or a gradient
              // blending source into target. Either lands in the same
              // custom property the fill classes read.
              const anchorTint = colorOf.get(
                linkColor === "target" ? link.target : link.source,
              )
              const tinted =
                linkColor === "gradient"
                  ? colorOf.has(link.source) || colorOf.has(link.target)
                  : anchorTint !== undefined
              const paint =
                linkColor === "gradient"
                  ? `url(#${gradientId}-${layoutLink.index})`
                  : anchorTint
              return (
                <path
                  // Parallel links between the same pair share the default
                  // id, so the input index keeps keys unique regardless.
                  key={`${id}#${layoutLink.index}`}
                  data-slot="flow-chart-link"
                  data-link-id={id}
                  data-tinted={tinted ? "true" : "false"}
                  data-emphasis={linkEmphasisByIndex.get(layoutLink.index)}
                  role="button"
                  tabIndex={0}
                  aria-pressed={selectionSet.has(id)}
                  aria-label={(linkLabel ?? defaultLinkLabel)(link)}
                  d={ribbonPaths[renderIndex]}
                  className={RIBBON_CLASSES}
                  style={
                    paint
                      ? ({ "--nessa-flow-chart-color": paint } as React.CSSProperties)
                      : undefined
                  }
                  onFocus={() => setFocusedLinkId(id)}
                  onBlur={() =>
                    setFocusedLinkId((previous) =>
                      previous === id ? null : previous,
                    )
                  }
                  onPointerEnter={() => {
                    setHovered({ kind: "link", id })
                    onHoveredLinkChange?.(id, link)
                  }}
                  onPointerLeave={() => {
                    setHovered((previous) =>
                      previous?.kind === "link" && previous.id === id
                        ? null
                        : previous,
                    )
                    onHoveredLinkChange?.(null, null)
                  }}
                  onClick={(event) =>
                    activateLink(link, event.metaKey || event.ctrlKey)
                  }
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault()
                      activateLink(link, event.metaKey || event.ctrlKey)
                    }
                  }}
                />
              )
            })}
            {/* A selected flow keeps a distinct mark — a centerline
                stroke — so it stays readable while other flows hover. */}
            {layout.links.map((layoutLink) =>
              selectionSet.has(linkIds[layoutLink.index]) ? (
                <path
                  key={`centerline-${layoutLink.index}`}
                  data-slot="flow-chart-centerline"
                  aria-hidden="true"
                  d={flowChartCenterlinePath(layoutLink, vertical)}
                  className="pointer-events-none fill-none stroke-foreground opacity-60 stroke-[1.5]"
                  strokeLinecap="round"
                />
              ) : null,
            )}
            {layout.nodes.map((node) => (
              <rect
                key={node.id}
                data-slot="flow-chart-node"
                data-node-id={node.id}
                data-tinted={colorOf.has(node.id) ? "true" : "false"}
                data-emphasis={nodeEmphasisById.get(node.id)}
                aria-hidden="true"
                x={vertical ? node.y : node.x}
                y={vertical ? node.x : node.y}
                width={vertical ? Math.max(node.height, 1) : node.width}
                height={vertical ? node.width : Math.max(node.height, 1)}
                rx={Math.min(4, node.width / 2)}
                className={BAR_CLASSES}
                style={
                  colorOf.has(node.id)
                    ? ({
                        "--nessa-flow-chart-color": colorOf.get(node.id),
                      } as React.CSSProperties)
                    : undefined
                }
                onPointerEnter={() =>
                  setHovered({ kind: "node", id: node.id })
                }
                onPointerLeave={() =>
                  setHovered((previous) =>
                    previous?.kind === "node" && previous.id === node.id
                      ? null
                      : previous,
                  )
                }
              />
            ))}
          </svg>
        ) : null}
        {layout && labelWidth > 0
          ? layout.nodes.map((node) => {
              const input = nodeById.get(node.id)!
              const context = nodeContext(node)
              const detail = renderNodeDetail
                ? renderNodeDetail(context)
                : formatValue(node.value)
              const first = node.column === 0
              const last = node.column === layout.columnCount - 1
              // Vertical labels always read inline (they sit above or
              // below a bar, where stacking would collide with ribbons);
              // horizontal labels read inline only at the sinks.
              const inline = vertical ? true : last
              // Flow-space coordinates: node.x runs along the flow axis,
              // node.y across it. Horizontal charts label into the side
              // gutters; vertical ones into the top/bottom gutters,
              // centered on the bar.
              const barCross = node.y + Math.max(node.height, 1) / 2
              const style: React.CSSProperties = vertical
                ? {
                    left: barCross,
                    top: first ? node.x - 8 : node.x + node.width + 8,
                    maxWidth: Math.max(labelWidth, 96),
                  }
                : {
                    top: barCross,
                    width: labelWidth - 8,
                    left: first ? node.x - labelWidth : node.x + node.width + 8,
                    // Middle-column labels overlay the ribbons beside
                    // their bar; only the outer columns get the reserved
                    // gutters.
                    maxWidth: first || last ? undefined : labelWidth - 8,
                  }
              return (
                <div
                  key={node.id}
                  data-slot="flow-chart-label"
                  data-emphasis={nodeEmphasisById.get(node.id)}
                  className={cn(
                    LABEL_CLASSES,
                    first ? "items-end text-right" : "items-start text-left",
                    // Inline labels read "Browsing · 22%"; stacked ones
                    // put the name over the detail.
                    inline && "flex-row items-baseline gap-1",
                    vertical &&
                      cn(
                        "-translate-x-1/2 items-center text-center",
                        first ? "-translate-y-full" : "translate-y-0",
                      ),
                  )}
                  style={style}
                >
                  <span className="max-w-full truncate">
                    {input.label ?? input.id}
                  </span>
                  {detail == null ? null : (
                    <span className="nessa-text-2 shrink-0 truncate">
                      {inline ? <>&middot; {detail}</> : detail}
                    </span>
                  )}
                </div>
              )
            })
          : null}
        {hoverDetail != null ? (
          <div
            ref={(element) => {
              hoverDetailRef.current = element
              // Position immediately on mount so the card never flashes
              // at a stale spot before the next pointer move.
              if (element) positionHoverDetail()
            }}
            data-slot="flow-chart-hover-detail"
            className="pointer-events-none absolute w-max"
            style={{ left: -9999, top: 0 }}
          >
            {hoverDetail}
          </div>
        ) : null}
      </div>
    </div>
  )
}

export { FlowChart, linkIdOf as flowChartLinkId }

/** @responsibility Pure flow-diagram (Sankey) geometry: assigns nodes to columns, scales heights to flow values, stacks columns to fill the box, allocates link slots along each node, and draws ribbon paths. No React, no DOM. */

/** A flow endpoint supplied by the host. */
export interface FlowChartNodeInput {
  /** Unique id links refer to. */
  id: string
}

/** A weighted flow between two nodes. */
export interface FlowChartLinkInput {
  /** Id of the node the flow leaves. */
  source: string
  /** Id of the node the flow enters. */
  target: string
  /** Magnitude of the flow. Non-positive links are ignored. */
  value: number
}

/**
 * How nodes choose their column when the flow leaves slack: "justify"
 * pushes sinks to the last column, "left"/"right" pack nodes toward an
 * edge by longest path from that edge, and "center" keeps depth order but
 * pulls late-starting sources up against their targets.
 */
export type FlowChartAlign = "left" | "justify" | "right" | "center"

/** Inputs the layout is computed from. */
export interface FlowChartLayoutOptions {
  nodes: readonly FlowChartNodeInput[]
  links: readonly FlowChartLinkInput[]
  /** Pixel width of the area the diagram fills. */
  width: number
  /** Pixel height of the area the diagram fills. */
  height: number
  /** Pixel width of each node bar. */
  nodeWidth: number
  /** Minimum vertical gap between stacked nodes in a column. */
  nodeGap: number
  /**
   * "justify" (default) pushes nodes without outgoing links into the last
   * column; "left" keeps every node at the earliest column its inputs
   * allow; "right" packs nodes toward the last column by longest path to a
   * sink; "center" pulls late-starting sources up against their targets.
   */
  align?: FlowChartAlign
  /**
   * Crossing-minimization passes over each column's node order (d3-style
   * barycenter relaxation). 0 (default) keeps the input order.
   */
  iterations?: number
}

/** A positioned node bar. */
export interface FlowChartLayoutNode {
  id: string
  /** Zero-based column, left to right. */
  column: number
  x: number
  y: number
  width: number
  height: number
  /** Flow through the node: max of incoming and outgoing sums. */
  value: number
  /** Sum of incoming link values. */
  inValue: number
  /** Sum of outgoing link values. */
  outValue: number
}

/** A positioned ribbon between two node bars. */
export interface FlowChartLayoutLink {
  /** Index into the original `links` input. */
  index: number
  source: string
  target: string
  value: number
  /** Top edge of the ribbon where it leaves the source bar. */
  sourceY: number
  /** Top edge of the ribbon where it enters the target bar. */
  targetY: number
  /** Right edge of the source bar. */
  sourceX: number
  /** Left edge of the target bar. */
  targetX: number
  /** Ribbon thickness in pixels. */
  thickness: number
}

/**
 * A data problem the layout tolerated instead of failing on. Transient
 * while data streams in; whatever remains once the stream settles is a
 * real data error the host should surface.
 */
export interface FlowChartLayoutIssue {
  kind:
    | "unknown-endpoint"
    | "self-link"
    | "duplicate-node"
    | "cycle"
    | "invalid-value"
  /** Human-readable summary of what was dropped or repaired. */
  message: string
  /** Index into the input `links` array, for link-scoped issues. */
  linkIndex?: number
  /** Offending node id, for node-scoped issues. */
  nodeId?: string
}

/** The computed diagram geometry. */
export interface FlowChartLayout {
  nodes: FlowChartLayoutNode[]
  links: FlowChartLayoutLink[]
  columnCount: number
  /** Sum of node values per column, in column order. */
  columnTotals: number[]
  /**
   * Everything the layout dropped or repaired to render this frame —
   * empty when the data was fully consistent.
   */
  issues: FlowChartLayoutIssue[]
}

interface NodeState {
  id: string
  order: number
  column: number
  inValue: number
  outValue: number
  value: number
}

/**
 * Longest-path column assignment over the link graph. Tolerant by design so
 * the chart survives partial, mid-stream data: callers pass pre-sanitized
 * nodes and links, and nodes trapped in a cycle fall back to one
 * deterministic input-order pass instead of failing.
 */
function assignColumns(
  nodes: readonly FlowChartNodeInput[],
  links: readonly FlowChartLinkInput[],
  issues: FlowChartLayoutIssue[],
): Map<string, number> {
  const outgoing = new Map<string, string[]>()
  const incoming = new Map<string, string[]>()
  const indegree = new Map<string, number>()
  for (const node of nodes) {
    outgoing.set(node.id, [])
    incoming.set(node.id, [])
    indegree.set(node.id, 0)
  }
  for (const link of links) {
    outgoing.get(link.source)!.push(link.target)
    incoming.get(link.target)!.push(link.source)
    indegree.set(link.target, indegree.get(link.target)! + 1)
  }

  const columns = new Map<string, number>()
  const queue: string[] = []
  for (const node of nodes) {
    if (indegree.get(node.id) === 0) {
      columns.set(node.id, 0)
      queue.push(node.id)
    }
  }
  while (queue.length > 0) {
    const id = queue.shift()!
    const depth = columns.get(id)!
    for (const next of outgoing.get(id)!) {
      // A node still waiting on cyclic predecessors keeps the deepest
      // column its resolved predecessors imply.
      columns.set(next, Math.max(columns.get(next) ?? 0, depth + 1))
      const remaining = indegree.get(next)! - 1
      indegree.set(next, remaining)
      if (remaining === 0) queue.push(next)
    }
  }
  // Nodes inside a cycle never drain from Kahn's queue. Place each in one
  // input-order pass after its already-placed predecessors — deterministic,
  // and the ribbons that close the loop simply flow backwards.
  const placed = new Set(columns.keys())
  for (const node of nodes) {
    if (placed.has(node.id)) continue
    issues.push({
      kind: "cycle",
      nodeId: node.id,
      message: `node ${node.id} sits in a cycle; placed by input order`,
    })
    let depth = 0
    for (const previous of incoming.get(node.id)!) {
      if (placed.has(previous)) {
        depth = Math.max(depth, (columns.get(previous) ?? 0) + 1)
      }
    }
    columns.set(node.id, depth)
    placed.add(node.id)
  }
  return columns
}

/**
 * Computes the full diagram geometry for one box size. Columns are spread
 * across the width; each column's node stack is scaled by the tightest
 * column and stretched vertically so every column fills the height, with
 * the slack shared evenly between its gaps.
 */
export function computeFlowChartLayout(options: FlowChartLayoutOptions): FlowChartLayout {
  const { links, nodeWidth, nodeGap } = options
  const width = Math.max(options.width, nodeWidth)
  const height = Math.max(options.height, 0)
  const align = options.align ?? "justify"

  // Tolerate partial, mid-stream data instead of failing: duplicate node
  // ids keep their first occurrence, and links that are non-positive,
  // self-referential, or waiting on a node that has not arrived yet are
  // simply not laid out this frame.
  const issues: FlowChartLayoutIssue[] = []
  const seen = new Set<string>()
  const nodes: FlowChartNodeInput[] = []
  for (const node of options.nodes) {
    if (seen.has(node.id)) {
      issues.push({
        kind: "duplicate-node",
        nodeId: node.id,
        message: `node ${node.id} appears more than once; kept the first`,
      })
      continue
    }
    seen.add(node.id)
    nodes.push(node)
  }
  const activeLinks: Array<FlowChartLinkInput & { index: number }> = []
  links.forEach((link, index) => {
    // NaN and Infinity would poison every derived coordinate; report and
    // drop them — a plain non-positive value is just "no flow yet".
    if (!Number.isFinite(link.value)) {
      issues.push({
        kind: "invalid-value",
        linkIndex: index,
        message: `link ${link.source} → ${link.target} has a non-finite value; dropped`,
      })
      return
    }
    if (link.value <= 0) return
    if (link.source === link.target) {
      issues.push({
        kind: "self-link",
        linkIndex: index,
        message: `link ${link.source} targets itself; dropped`,
      })
      return
    }
    if (!seen.has(link.source) || !seen.has(link.target)) {
      issues.push({
        kind: "unknown-endpoint",
        linkIndex: index,
        message: `link ${link.source} → ${link.target} references a node not (yet) present; dropped`,
      })
      return
    }
    activeLinks.push({ ...link, index })
  })

  const columns = assignColumns(nodes, activeLinks, issues)

  const states = new Map<string, NodeState>()
  nodes.forEach((node, order) => {
    states.set(node.id, {
      id: node.id,
      order,
      column: columns.get(node.id) ?? 0,
      inValue: 0,
      outValue: 0,
      value: 0,
    })
  })
  for (const link of activeLinks) {
    states.get(link.source)!.outValue += link.value
    states.get(link.target)!.inValue += link.value
  }
  for (const state of states.values()) {
    state.value = Math.max(state.inValue, state.outValue)
  }

  let columnCount = 0
  for (const state of states.values()) {
    columnCount = Math.max(columnCount, state.column + 1)
  }
  const hadCycle = issues.some((issue) => issue.kind === "cycle")
  if (align === "justify" && columnCount > 1) {
    for (const state of states.values()) {
      // A node with no flow at all is not a sink — leaving it at its
      // depth keeps a just-streamed node from teleporting across the
      // chart until its links arrive.
      if (state.outValue === 0 && state.inValue > 0) {
        state.column = columnCount - 1
      }
    }
  } else if (align === "right" && columnCount > 1 && !hadCycle) {
    // With a cycle, the reversed-graph heights collapse while the forward
    // fallback inflates columnCount, inverting the chart — fall back to
    // depth placement instead (the cycle is already reported).
    // Longest path TO a sink, computed on the reversed graph, packs every
    // node as far right as its outputs allow.
    const heights = assignColumns(
      nodes,
      activeLinks.map((link) => ({ ...link, source: link.target, target: link.source })),
      [],
    )
    for (const state of states.values()) {
      state.column = columnCount - 1 - (heights.get(state.id) ?? 0)
    }
  } else if (align === "center" && columnCount > 1) {
    // Late-starting sources sit one column before their earliest target
    // instead of at the far left.
    for (const state of states.values()) {
      if (state.inValue > 0 || state.outValue === 0) continue
      let earliestTarget = Infinity
      for (const link of activeLinks) {
        if (link.source !== state.id) continue
        earliestTarget = Math.min(
          earliestTarget,
          states.get(link.target)!.column,
        )
      }
      if (Number.isFinite(earliestTarget)) {
        state.column = Math.max(0, earliestTarget - 1)
      }
    }
  }

  const byColumn: NodeState[][] = Array.from({ length: columnCount }, () => [])
  for (const state of states.values()) {
    byColumn[state.column].push(state)
  }
  for (const column of byColumn) {
    column.sort((a, b) => a.order - b.order)
  }

  // Barycenter relaxation: each pass re-sorts every column by the mean
  // position of the nodes it is linked to, alternating sweep direction —
  // the d3-sankey recipe for untangling ribbon crossings. Zero passes
  // keeps the host's input order.
  const iterations = Math.max(0, Math.floor(options.iterations ?? 0))
  if (iterations > 0 && columnCount > 1) {
    const ordinal = new Map<string, number>()
    const reindex = () => {
      for (const column of byColumn) {
        column.forEach((node, index) => {
          ordinal.set(node.id, (index + 0.5) / column.length)
        })
      }
    }
    reindex()
    // Adjacency once, so each relax pass touches only a node's own links
    // instead of scanning every link per node.
    type Adjacent = { counterpart: string; value: number }
    const incomingOf = new Map<string, Adjacent[]>()
    const outgoingOf = new Map<string, Adjacent[]>()
    for (const link of activeLinks) {
      let into = incomingOf.get(link.target)
      if (!into) incomingOf.set(link.target, (into = []))
      into.push({ counterpart: link.source, value: link.value })
      let from = outgoingOf.get(link.source)
      if (!from) outgoingOf.set(link.source, (from = []))
      from.push({ counterpart: link.target, value: link.value })
    }
    const relax = (useIncoming: boolean, column: NodeState[]) => {
      const adjacency = useIncoming ? incomingOf : outgoingOf
      const scores = new Map<string, number>()
      for (const node of column) {
        let weight = 0
        let sum = 0
        for (const edge of adjacency.get(node.id) ?? []) {
          sum += edge.value * ordinal.get(edge.counterpart)!
          weight += edge.value
        }
        scores.set(node.id, weight > 0 ? sum / weight : ordinal.get(node.id)!)
      }
      column.sort(
        (a, b) =>
          scores.get(a.id)! - scores.get(b.id)! || a.order - b.order,
      )
    }
    for (let pass = 0; pass < iterations; pass += 1) {
      for (let index = 1; index < columnCount; index += 1) {
        relax(true, byColumn[index])
        reindex()
      }
      for (let index = columnCount - 2; index >= 0; index -= 1) {
        relax(false, byColumn[index])
        reindex()
      }
    }
  }

  // The tightest column sets the value-to-pixel scale so every column fits.
  let scale = Infinity
  for (const column of byColumn) {
    const total = column.reduce((sum, node) => sum + node.value, 0)
    if (total <= 0) continue
    const available = height - nodeGap * (column.length - 1)
    scale = Math.min(scale, Math.max(available, 0) / total)
  }
  if (!Number.isFinite(scale)) scale = 0

  // Never negative: in a box narrower than the columns the bars touch
  // and overflow rightward rather than overlapping into each other.
  const columnGap =
    columnCount > 1
      ? Math.max(0, (width - nodeWidth * columnCount) / (columnCount - 1))
      : 0

  const positioned = new Map<string, FlowChartLayoutNode>()
  const columnTotals: number[] = []
  byColumn.forEach((column, columnIndex) => {
    const total = column.reduce((sum, node) => sum + node.value, 0)
    columnTotals.push(total)
    const stack = total * scale
    // Share the leftover height evenly among the gaps so the column fills
    // the box; a lone node centers instead.
    const slack = Math.max(height - stack - nodeGap * (column.length - 1), 0)
    const gap =
      column.length > 1 ? nodeGap + slack / (column.length - 1) : nodeGap
    let y = column.length > 1 ? 0 : slack / 2
    const x = columnIndex * (nodeWidth + columnGap)
    for (const node of column) {
      const nodeHeight = node.value * scale
      positioned.set(node.id, {
        id: node.id,
        column: columnIndex,
        x,
        y,
        width: nodeWidth,
        height: nodeHeight,
        value: node.value,
        inValue: node.inValue,
        outValue: node.outValue,
      })
      y += nodeHeight + gap
    }
  })

  // Slot links along each bar, ordered by the counterpart bar's vertical
  // position so ribbons fan out without gratuitous crossings.
  const outCursor = new Map<string, number>()
  const inCursor = new Map<string, number>()
  const bySourceOrder = [...activeLinks].sort((a, b) => {
    const ay = positioned.get(a.target)!.y - positioned.get(b.target)!.y
    return ay !== 0 ? ay : a.index - b.index
  })
  const sourceY = new Map<number, number>()
  for (const link of bySourceOrder) {
    const bar = positioned.get(link.source)!
    const offset = outCursor.get(link.source) ?? 0
    sourceY.set(link.index, bar.y + offset)
    outCursor.set(link.source, offset + link.value * scale)
  }
  const byTargetOrder = [...activeLinks].sort((a, b) => {
    const ay = positioned.get(a.source)!.y - positioned.get(b.source)!.y
    return ay !== 0 ? ay : a.index - b.index
  })
  const targetY = new Map<number, number>()
  for (const link of byTargetOrder) {
    const bar = positioned.get(link.target)!
    const offset = inCursor.get(link.target) ?? 0
    targetY.set(link.index, bar.y + offset)
    inCursor.set(link.target, offset + link.value * scale)
  }

  const layoutLinks: FlowChartLayoutLink[] = activeLinks.map((link) => {
    const source = positioned.get(link.source)!
    const target = positioned.get(link.target)!
    return {
      index: link.index,
      source: link.source,
      target: link.target,
      value: link.value,
      sourceY: sourceY.get(link.index)!,
      targetY: targetY.get(link.index)!,
      sourceX: source.x + source.width,
      targetX: target.x,
      thickness: link.value * scale,
    }
  })

  return {
    nodes: [...positioned.values()],
    links: layoutLinks,
    columnCount,
    columnTotals,
    issues,
  }
}

/**
 * SVG path for a link's filled ribbon. `curvature` in [0, 1] moves the
 * bezier control points from the bar edges (0, straight taper) toward the
 * flow-axis midpoint (1, the classic S curve). Layout coordinates live in
 * flow space — sourceX/targetX along the flow axis, sourceY/targetY across
 * it; `vertical` emits each point with the axes swapped so the same
 * geometry renders top-to-bottom.
 */
export function flowChartRibbonPath(
  link: FlowChartLayoutLink,
  curvature: number,
  vertical = false,
): string {
  const { sourceX, targetX, sourceY, targetY } = link
  // Ribbons thinner than a hairline stay visible.
  const thickness = Math.max(link.thickness, 1)
  const c0 = sourceX + (targetX - sourceX) * 0.5 * curvature
  const c1 = targetX - (targetX - sourceX) * 0.5 * curvature
  const s0 = sourceY
  const s1 = sourceY + thickness
  const t0 = targetY
  const t1 = targetY + thickness
  const at = (flow: number, cross: number) =>
    vertical ? `${cross} ${flow}` : `${flow} ${cross}`
  return [
    `M ${at(sourceX, s0)}`,
    `C ${at(c0, s0)} ${at(c1, t0)} ${at(targetX, t0)}`,
    `L ${at(targetX, t1)}`,
    `C ${at(c1, t1)} ${at(c0, s1)} ${at(sourceX, s1)}`,
    "Z",
  ].join(" ")
}

/**
 * SVG path for the ribbon's center line — an emphasis stroke along a
 * link. Same flow-space semantics as `flowChartRibbonPath`.
 */
export function flowChartCenterlinePath(
  link: FlowChartLayoutLink,
  vertical = false,
): string {
  const { sourceX, targetX, sourceY, targetY } = link
  const thickness = Math.max(link.thickness, 1)
  const mid = (sourceX + targetX) / 2
  const s = sourceY + thickness / 2
  const t = targetY + thickness / 2
  const at = (flow: number, cross: number) =>
    vertical ? `${cross} ${flow}` : `${flow} ${cross}`
  return `M ${at(sourceX, s)} C ${at(mid, s)} ${at(mid, t)} ${at(targetX, t)}`
}
